<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Search, Plus, RotateCw, ArrowUpRight, TicketCheck } from '@lucide/vue'
import { ticketApi } from '@/api/modules'
import type { PageResponse, Ticket } from '@/types/api'
import BaseModal from '@/components/BaseModal.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import PaginationBar from '@/components/PaginationBar.vue'
const route=useRoute();const router=useRouter();const page=ref<PageResponse<Ticket>>({records:[],total:0,pageNum:1,pageSize:10});const loading=ref(false);const error=ref('');const showCreate=ref(false);const creating=ref(false)
const filters=reactive({keyword:'',status:'',priority:'',pageNum:1,pageSize:10});const form=reactive({title:'',description:'',priority:'MEDIUM'})
async function load(){loading.value=true;error.value='';try{page.value=await ticketApi.page(Object.fromEntries(Object.entries(filters).filter(([,v])=>v!=='')))}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function create(){creating.value=true;error.value='';try{const ticket=await ticketApi.create(form);showCreate.value=false;await router.push(`/tickets/${ticket.id}`)}catch(e){error.value=e instanceof Error?e.message:'创建失败'}finally{creating.value=false}}
function reset(){Object.assign(filters,{keyword:'',status:'',priority:'',pageNum:1,pageSize:10});load()}
watch(()=>route.query.create,v=>{if(v==='1')showCreate.value=true},{immediate:true});onMounted(load)
</script>
<template><div class="stack-page"><section class="page-lead"><div><span class="eyebrow">TICKET WORKSPACE</span><h2>工单中心</h2><p>创建、跟踪并完成每一个运维问题闭环。</p></div><button class="button primary" @click="showCreate=true"><Plus :size="18"/>新建工单</button></section><section class="filter-bar"><div class="search-box"><Search :size="18"/><input v-model.trim="filters.keyword" placeholder="搜索工单编号、标题或描述" @keyup.enter="filters.pageNum=1;load()"/></div><select v-model="filters.status" @change="filters.pageNum=1;load()"><option value="">全部状态</option><option value="CREATED">待接单</option><option value="PROCESSING">处理中</option><option value="RESOLVED">待确认</option><option value="CLOSED">已关闭</option></select><select v-model="filters.priority" @change="filters.pageNum=1;load()"><option value="">全部优先级</option><option value="URGENT">紧急</option><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select><button class="button secondary" @click="reset"><RotateCw :size="16"/>重置</button></section><section class="panel table-panel"><div v-if="error" class="inline-error">{{error}}</div><div v-if="loading" class="loading-state">正在加载工单…</div><div v-else-if="!page.records.length" class="empty-state"><TicketCheck :size="38"/><strong>没有符合条件的工单</strong><span>调整筛选条件或创建一张新工单。</span></div><div v-else class="responsive-table"><table><thead><tr><th>工单</th><th>优先级</th><th>状态</th><th>创建人 / 处理人</th><th>更新时间</th><th></th></tr></thead><tbody><tr v-for="ticket in page.records" :key="ticket.id"><td><RouterLink class="table-title" :to="`/tickets/${ticket.id}`"><strong>{{ticket.title}}</strong><span>{{ticket.ticketNo}}</span></RouterLink></td><td><StatusBadge :value="ticket.priority"/></td><td><StatusBadge :value="ticket.status"/></td><td><span class="identity-pair">#{{ticket.creatorId}} <i>→</i> {{ticket.assigneeId?'#'+ticket.assigneeId:'待分配'}}</span></td><td>{{new Date(ticket.updateTime).toLocaleString('zh-CN')}}</td><td><RouterLink class="icon-button" :to="`/tickets/${ticket.id}`"><ArrowUpRight :size="17"/></RouterLink></td></tr></tbody></table></div><PaginationBar v-if="page.total" :page="filters.pageNum" :page-size="filters.pageSize" :total="page.total" @change="p=>{filters.pageNum=p;load()}"/></section><BaseModal v-if="showCreate" title="新建运维工单" @close="showCreate=false"><form class="form-grid" @submit.prevent="create"><label>工单标题<input v-model.trim="form.title" required maxlength="128" placeholder="简明描述问题，例如：生产服务器磁盘使用率告警"/></label><label>优先级<select v-model="form.priority"><option value="LOW">低</option><option value="MEDIUM">中</option><option value="HIGH">高</option><option value="URGENT">紧急</option></select></label><label class="full">问题描述<textarea v-model.trim="form.description" required maxlength="10000" rows="7" placeholder="描述现象、影响范围、发生时间和已尝试的操作…"/></label><p v-if="error" class="form-error full">{{error}}</p><div class="form-actions full"><button type="button" class="button secondary" @click="showCreate=false">取消</button><button class="button primary" :disabled="creating">{{creating?'创建中…':'创建工单'}}</button></div></form></BaseModal></div></template>
